-- gap cmp:55:14:1, written by an automated writer
test("breakit Net.Provider: removing the driver addon lets Wuber's driver go online", function()
    local w = T.newWorld()
    local d = T.driver(w, T.TESTCHAR)
    T.settle(w)
    d.env.WuberAPI.SetDriver({ name = "Other Rides", beacon = function() return nil end, onRequest = function() end })
    w:advance(2)
    d.env.WuberAPI.SetDriver(nil)
    w:advance(2)
    T.goOnline(d, { price = 500 })
    w:advance(2)
    local beacons = w:messages("D", T.TESTCHAR)
    ok(#beacons > 0, "the driver's beacon is sent after the addon is removed")
    T.clean(w)
end)

